song_ids = {}
for title, artist in songs:
    result = apis.spotify.search_songs(access_token=spotify_token, query=title, page_index=0, page_limit=20)
    # Check if result is a list or dict
    if isinstance(result, dict):
        # maybe has 'songs' key
        items = result.get('songs', [])
    else:
        items = result
    # Find matching song by title and artist
    found = None
    for song in items:
        if song.get('title', '').lower() == title.lower():
            # Check artist match
            artists = song.get('artists', [])
            artist_names = [a.get('name', '') for a in artists] if isinstance(artists, list) else []
            if any(a.lower() == artist.lower() for a in artist_names):
                found = song
                break
    if found:
        song_ids[title] = found['song_id']
        print(f"Found: {title} - {artist} -> ID {found['song_id']}")
    else:
        print(f"NOT FOUND: {title} - {artist}")

print(f"\nTotal found: {len(song_ids)}")

