import json

# Get the file content from saved result
file_content = _mem['s10']['content']
# Parse lines, skip header and empty lines
lines = [line.strip() for line in file_content.splitlines() if line.strip() and not line.startswith('#')]
archive_songs = []
for line in lines:
    # Format: "Title by Artist" or "Title - Artist"? The file content shows "Title by Artist" based on history.
    # Let's check the actual content: from history, it's "Title by Artist" (e.g., "The Intangible Essence of You by Seraphina Dawn")
    if ' by ' in line:
        title, artist = line.split(' by ', 1)
    elif ' - ' in line:
        title, artist = line.split(' - ', 1)
    else:
        continue
    archive_songs.append((title.strip(), artist.strip()))

# Get spotify token
spotify_token = _mem['s13']['access_token']

# Search for each song and get its ID
archive_song_ids = {}
for title, artist in archive_songs:
    # Search by title
    result = spotify.search_songs(access_token=spotify_token, query=title, page_index=0, page_limit=20)
    # result is a list of songs? Need to check the response schema. From history, search_songs returns a list of songs.
    # We'll iterate and match artist case-insensitively
    found = None
    for song in result:
        # song has 'title' and 'artists' array
        if song.get('title', '').lower() == title.lower():
            # Check if any artist matches
            for art in song.get('artists', []):
                # art might be a dict with 'name' or a string? Need to check schema. From history, artists array contains objects with name.
                if isinstance(art, dict):
                    artist_name = art.get('name', '')
                else:
                    artist_name = str(art)
                if artist_name.lower() == artist.lower():
                    found = song['song_id']
                    break
            if found:
                break
    if found:
        archive_song_ids[title] = found
    else:
        print(f"Not found: {title} - {artist}")

print(f"Total archive songs mapped: {len(archive_song_ids)}")
print(archive_song_ids)

