# Let's cross-reference the archive song IDs with the playlist song IDs
archive_song_ids = {117, 216, 246, 201, 215, 41, 153, 188, 96, 203, 80, 238, 104, 46, 88, 278, 160, 291}
playlists = _mem['s19']

# Find which playlists contain which archive songs
playlist_archive_map = {}
for pl in playlists:
    pl_id = pl['playlist_id']
    pl_title = pl['title']
    matching = [sid for sid in pl['song_ids'] if sid in archive_song_ids]
    if matching:
        playlist_archive_map[pl_id] = {'title': pl_title, 'matching_song_ids': matching}
        print(f"Playlist {pl_id} ({pl_title}) contains archive songs: {matching}")

# Collect all archive songs that appear in any playlist
all_removed = set()
for pl in playlists:
    all_removed.update([sid for sid in pl['song_ids'] if sid in archive_song_ids])
print(f"\nAll archive songs present in playlists: {sorted(all_removed)}")
print(f"Count: {len(all_removed)}")

